/// url = 'http://octofhir.com/ccda-fhir/StructureMap/fhir-status-to-cda'
/// name = 'FhirStatusToCda'
/// title = 'US Core functional and cognitive status to C-CDA'
/// status = 'active'
/// description = 'US Core 6.1.0 Observations of the functional-status and cognitive-status categories to Functional Status and Mental Status entries (C-CDA 5.0.0): panels as organizers, screening and assessment as Assessment Scale Observations, others as status observations. The inverse of cda-status-to-fhir.'

map "http://octofhir.com/ccda-fhir/StructureMap/fhir-status-to-cda" = "FhirStatusToCda"

uses "http://hl7.org/fhir/StructureDefinition/Observation" alias Observation as source
uses "http://hl7.org/fhir/StructureDefinition/Bundle" alias Bundle as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Observation" alias CdaObservation as target
uses "http://hl7.org/cda/stds/core/StructureDefinition/Organizer" alias Organizer as target
uses "http://hl7.org/cda/stds/core/StructureDefinition/Entry" alias Entry as target
uses "http://hl7.org/cda/stds/core/StructureDefinition/CD" alias CD as target

imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-datatypes-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-participants-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-results-to-cda"
imports "http://octofhir.com/ccda-fhir/StructureMap/fhir-social-to-cda"

// An entry of a status section: a panel is an organizer, a screening an assessment scale, any
// other observation a status observation. `kind` is the section: `functional` or `cognitive`.
group StatusEntry(source observation : Observation, source bundle : Bundle, source kind : string, target entry : Entry) {
  observation where (hasMember.exists() and category.coding.where(code = 'survey').empty()) -> entry.organizer as organizer then StatusOrganizer(observation, bundle, kind, organizer);
  observation where (category.coding.where(code = 'survey').exists()) -> entry.observation as cda then SocialToCda(observation, bundle, cda);
  observation where (hasMember.empty() and category.coding.where(code = 'survey').empty()) -> entry.observation as cda then StatusObservationToCda(observation, bundle, kind, cda);
}

group StatusOrganizer(source panel : Observation, source bundle : Bundle, source kind : string, target organizer : Organizer) {
  panel -> organizer.classCode = 'CLUSTER', organizer.moodCode = 'EVN';
  kind where ($this = 'cognitive') -> organizer.templateId as template, template.root = '2.16.840.1.113883.10.20.22.4.75', template.extension = '2024-05-01';
  kind where ($this = 'functional') -> organizer.templateId as template, template.root = '2.16.840.1.113883.10.20.22.4.66', template.extension = '2014-06-09';
  panel.identifier as identifier -> organizer.id as id then IdentifierToII(identifier, id);
  panel where (identifier.empty()) -> uuid() as u, organizer.id as id, id.root = evaluate(u, $this.upper());
  panel.code as code -> organizer.code = create('CD') as c then CodeableConceptToCD(code, c);
  panel -> organizer.statusCode as sc, sc.code = 'completed';
  panel.effective : dateTime as effective -> organizer.effectiveTime as time then DateTimeToTS(effective, time);
  panel.effective : Period as effective -> organizer.effectiveTime as time then PeriodToIVLTS(effective, time);
  panel.hasMember as ref then {
    bundle.entry as entry where (fullUrl = %ref.reference) then {
      entry.resource : Observation as member -> organizer.component as component, component.observation as cda then StatusObservationToCda(member, bundle, kind, cda);
    };
  };
}

// A status observation: the template's code (54522-8 Functional status, 8693-4 Mental status) with
// the observation's own codes as translations.
group StatusObservationToCda(source observation : Observation, source bundle : Bundle, source kind : string, target cda : CdaObservation) {
  observation -> cda.classCode = 'OBS', cda.moodCode = 'EVN';
  kind where ($this = 'cognitive') -> cda.templateId as template, template.root = '2.16.840.1.113883.10.20.22.4.74', template.extension = '2024-05-01';
  kind where ($this = 'functional') -> cda.templateId as template, template.root = '2.16.840.1.113883.10.20.22.4.67', template.extension = '2014-06-09';
  observation.identifier as identifier -> cda.id as id then IdentifierToII(identifier, id);
  observation where (identifier.empty()) -> uuid() as u, cda.id as id, id.root = evaluate(u, $this.upper());
  observation -> cda.code = create('CD') as statusCode, statusCode.codeSystem = '2.16.840.1.113883.6.1' then {
    kind where ($this = 'cognitive') -> statusCode.code = '8693-4', statusCode.displayName = 'Mental status';
    kind where ($this = 'functional') -> statusCode.code = '54522-8', statusCode.displayName = 'Functional status';
    observation.code as ownCode then {
      ownCode.text as text -> statusCode.originalText as original, original.xmlText = text;
      ownCode.coding as coding where (iif(system = 'http://loinc.org' and code in ('8693-4' | '54522-8'), false, true)) -> statusCode.translation as translation then CodingToCD(coding, translation);
    };
  };
  observation -> cda.statusCode as sc, sc.code = 'completed';
  observation then EffectiveToCda(observation, cda);
  observation where (effective.empty()) -> cda.effectiveTime as time, time.nullFlavor = 'UNK';
  observation then ObservationBodyToCda(observation, bundle, cda);
  // The template requires a value.
  observation where (value.empty() and dataAbsentReason.empty()) -> cda.value = create('CD') as value, value.nullFlavor = 'NI';
}
